                      0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

            Vector256<byte> mask0F = Vector256.Create((byte)0x0F);

            ref byte refData = ref MemoryMarshal.GetReference(data);

            for (; i + 32 <= data.Length; i += 32)
